ervice_role=X/postgres}"},{"schema":"public","proname":"upsert_enterprise_cost_center_v1","args":"p_enterprise_id uuid, p_cost_center_id uuid, p_site_id uuid, p_code text, p_name text, p_department text, p_status text","definition_md5":"ec79b5f532e291d036b077105235b9e7","proacl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}"},{"schema":"public","proname":"upsert_enterprise_dispatch_policy","args":"p_enterprise_id uuid, p_policy_id uuid, p_site_id uuid, p_service_category text, p_mode text, p_internal_offer_limit integer, p_offer_ttl_minutes integer, p_fallback_after_minutes integer, p_status text","definition_md5":"fb3c6e2bcaae8e6547da6e7599d4c213","proacl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}"},{"schema":"public","proname":"upsert_enterprise_equipment_v1","args":"p_enterprise_id uuid, p_equipment_id uuid, p_site_id uuid, p_name text, p_category text, p_asset_code text, p_manufacturer text, p_model text, p_serial_number text, p_installed_at date, p_criticality text, p_status text, p_notes text","definition_md5":"672838a6f949c4315ba874b694bb24b0","proacl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}"},{"schema":"public","proname":"upsert_enterprise_maintenance_plan_v1","args":"p_enterprise_id uuid, p_plan_id uuid, p_site_id uuid, p_name text, p_service_category text, p_description text, p_urgency text, p_frequency text, p_interval_count integer, p_next_due_at timestamp with time zone, p_reminder_hours integer, p_status text","definition_md5":"2a8f495b65b3f4d24d565c94c90db0ac","proacl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}"},{"schema":"public","proname":"upsert_enterprise_purchase_order_v1","args":"p_enterprise_id uuid, p_purchase_order_id uuid, p_cost_center_id uuid, p_site_id uuid, p_reference text, p_approved_amount numeric, p_status text, p_notes text","definition_md5":"185b9fdfc02027bd1fa6e4b5d28caefd","proacl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}"},{"schema":"public","proname":"upsert_enterprise_rafi_followup_v1","args":"p_enterprise_id uuid, p_target_type text, p_target_id uuid, p_followup_kind text, p_status text, p_note text","definition_md5":"d548ad2a186a91616304a159faa861a4","proacl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}"}]$snapshot$::jsonb) LOOP
  sig:=format('%I.%I(%s)',f->>'schema',f->>'proname',f->>'args');
  SELECT md5(pg_get_functiondef(p.oid)),p.proacl::text INTO actual,actual_acl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=f->>'schema' AND p.proname=f->>'proname' AND pg_get_function_identity_arguments(p.oid)=f->>'args';
  IF actual IS DISTINCT FROM f->>'definition_md5' OR actual_acl IS DISTINCT FROM f->>'proacl' THEN RAISE EXCEPTION 'BASELINE_FUNCTION_DRIFT: %',sig; END IF;
 END LOOP;
END $gate$;
-- Compare the resulting catalog to baseline-fingerprints.json. No business rows.
SELECT n.nspname AS schema,c.relname AS table,c.relacl::text AS acl,c.relrowsecurity AS rls,c.reloptions
FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND c.relname=ANY(ARRAY['artisan_review_stats','artisans','artisans_available','claim_requests','claims_pending','enterprise_accounts','enterprise_internal_assignments','enterprise_members','enterprise_request_context','enterprise_request_sla','enterprise_sites','enterprise_sla_status','enterprise_workforce_workers','missions','quotes','service_requests']) ORDER BY 1,2;
SELECT schemaname,tablename,policyname,roles,cmd,qual,with_check FROM pg_policies
WHERE schemaname='public' AND tablename=ANY(ARRAY['artisan_review_stats','artisans','artisans_available','claim_requests','claims_pending','enterprise_accounts','enterprise_internal_assignments','enterprise_members','enterprise_request_context','enterprise_request_sla','enterprise_sites','enterprise_sla_status','enterprise_workforce_workers','missions','quotes','service_requests']) ORDER BY tablename,policyname;
COMMIT;
